```c
case post_element:
    if (isspace((unsigned char) *cp)) {
        continue;
    }
    if (*cp == ',') {
        state = await_attr;
    } else if (*cp == '}') {
        ++cp;
        goto good_parse;
    }
```

When `*cp == '}'`, `++cp` moves to the next char. If that's NUL, `good_parse` reads `isspace(0)` = false. Fine.

OK, let me look at the `await_attr` case:
```c
case await_attr:
    if (isspace((unsigned char) *cp)) {
        continue;
    }
    if (*cp == '"') {
        state = in_attr;
        pattr = attrbuf;
        ...
    } else if (*cp == '}') {
        break;
    }
```

When `*cp == '}'`, it `break`s out of the switch. Then the outer `for` loop does `cp++` and checks `*cp != '\0'`. Fine.

Let me look at the `in_attr` case:
```c
case in_attr:
    if (*cp == '"') {
        *pattr++ = '\0';
        ...
    } else if (pattr >= attrbuf + JSON_ATTR_MAX - 1) {
        return JSON_ERR_ATTRLEN;
    } else {
        *pattr++ = *cp;
    }
    break;
```

Fine.

Let me look at the `await_value` case:
```c
case await_value:
    if (isspace((unsigned char) *cp) || *cp == ':') {
        continue;
    }
    if (*cp == '[') {
        ...
    } else if (cursor->type == t_array) {
        ...
    } else if (*cp == '"') {
        value_quoted = true;
        state = in_val_string;
        pval = valbuf;
    } else {
        value_quoted = false;
        state = in_val_token;
        pval = valbuf;
        *pval++ = *cp;
    }
    break;
```

Fine.

Let me look at the `in_val_token` case:
```c
case in_val_token:
    if (NULL == pval) {
        return JSON_ERR_NULLPTR;
    }
    if (isspace((unsigned char) *cp) || *cp == ',' || *cp == '}') {
        *pval = '\0';
        state = post_val;
        if (*cp == '}' || *cp == ',') {
